// index.d.ts
/**
 * Windows功能模块 主要功能：
 * ```js
 * class{};             // 类
 * fun();               // 函数
 * ```
 * ---
 *   -
 * ```js
 *  // 基础示例
 *  const { flun } = require('flun');
 *
 * ```
 *   -
 */
declare module 'flun' {
    // import { xyz } from 'xyz';

    // ============ 类 ============

    /**
     * 占位类
     * ```js
     *  // 配置示例
     *  const { abc } = require('flun');
     *
     * ```
     */
    export class abc { }

    // ============ 函数 ============

    /**
     * 占位函数
     * ```js
     * const {fun} = require('flun');
     *
     * ```
     */
    export function fun(): void;
}